const source=usableActivitySource(item,sources);
const display=normalizeStationConnections(item,locale().startsWith('en')?'en':'id');
const selected=display.routeOptions?.[item.selectedRoute||0];
return <div className="ai-item-details">{selected&&<div className="route-recommendation"><strong>{selected.kind==='hemat'?tr('ui_0001'):selected.kind==='cepat'?tr('ui_0002'):tr('ui_0003')}</strong>{onSelectRoute&&<div className="route-choice">{item.routeOptions?.map((option,i)=><button type="button" className="secondary" disabled={item.paid||item.bookingHold} aria-pressed={i===(item.selectedRoute||0)} key={option.kind} onClick={()=>onSelectRoute(i)}>{tr('route_'+option.kind)}</button>)}</div>}<ol>{selected.legs.map((leg,i)=><li key={i}><b>{localize(leg.mode)}</b>{leg.sourceRelevant===false&&<small>{tr('route_source_unverified')}</small>}<span>{localize(leg.fromPlace)} → {localize(leg.toPlace)}</span><small>{item.routePriceQuotes?.find(q=>q.id===item.id+'::'+i)?tr('msg_0000')+money(item.routePriceQuotes.find(q=>q.id===item.id+'::'+i)!.amountIDR):leg.fare?tr('msg_0001')+leg.fare:tr('ui_0004')}{leg.duration?' · '+leg.duration:''}{leg.checkedAt?tr('checked_date',{date:leg.checkedAt}):''}</small><a href={'https://www.google.com/maps/dir/?'+new URLSearchParams({api:'1',origin:leg.fromPlace,destination:leg.toPlace,travelmode:/jalan kaki|walking/i.test(leg.mode)?'walking':/taksi|taxi|grab/i.test(leg.mode)?'driving':'transit'})} target="_blank" rel="noopener noreferrer">{tr('ui_0005')}</a></li>)}</ol><p>{narrative(selected.summary)}</p></div>}{!source&&item.category==='Wisata'&&<p className="inline-note">{tr('ai_source_unverified')}</p>}<InfoNote label={tr('information_item',{name:narrative(item.title)})}><p>{narrative(item.note)}</p>{display.routeOptions?.map((option,i)=><section key={i}><strong>{tr('route_'+option.kind)}</strong><p>{narrative(option.summary)}</p>{option.legs.map((leg,j)=><p key={j}>{leg.sourceRelevant===false&&<small>{tr('route_source_unverified')}<br/></small>}{localize(leg.mode)} · {localize(leg.fromPlace)} → {localize(leg.toPlace)}<br/>{narrative(leg.note)} {leg.sourceRelevant!==false&&<a href={leg.sourceUrl} target="_blank" rel="noopener noreferrer">{tr('ui_0006')}</a>}</p>)}</section>)}{item.locationCity&&<small>{item.locationCity}{' '+tr('ui_0007')}</small>}<div className="activity-links">{source&&<a href={source} target="_blank" rel="noopener noreferrer">{tr('ui_0008')}</a>}{route&&<a href={'https://www.google.com/maps/dir/?'+route} target="_blank" rel="noopener noreferrer">{tr('ui_0009')}</a>}</div></InfoNote></div>;

const requestedStay=requestedAirportNight?stay(requestedAirportNight):undefined;
const unresolvedAirport=requestedStay&&!withinAirportScope(requestedStay.geo);
const airportAnchor=(s:string|undefined)=>!!s&&/^(?:klia|klia area|area klia|hotel(?: dekat| near)? klia|penginapan(?: dekat)? klia)$/i.test(s.trim());
const airportOrigin=unresolvedAirport&&item.day===(requestedAirportNight||0)+1&&airportAnchor(item.fromPlace);
const airportDestination=unresolvedAirport&&item.day===requestedAirportNight&&airportAnchor(item.toPlace);
const fromPlace=airportOrigin?(requestedStay.place||requestedStay.title):replace(item.fromPlace,fromStay),toPlace=airportDestination?(requestedStay.place||requestedStay.title):replace(item.toPlace,current);

// Expanding a short hotel name in the display title does not change the
// structured journey. Keep its researched legs/quotes when endpoints agree.
if(fromPlace===item.fromPlace&&toPlace===item.toPlace&&fromPlace&&toPlace)return {...item,title:fromPlace+' → '+toPlace};
return {...item,title:fromPlace&&toPlace?fromPlace+' → '+toPlace:title,fromPlace,toPlace,place:undefined,geo:undefined,mode:undefined,minutes:undefined,routeOptions:undefined,selectedRoute:undefined,routePriceQuotes:undefined,priceQuote:undefined,bookingUrl:undefined,sourceUrl:undefined,routeKey:undefined,price:0,priceUnknown:true,shared:false,note:airportOrigin||airportDestination?(language==='en'?'An airport hotel has not been verified. The selected hotel is retained; check this new connection in Google Maps. Duration and fare are unavailable.':'Hotel dekat bandara belum terverifikasi. Hotel terpilih tetap dipakai; periksa sambungan baru ini di Google Maps. Durasi dan tarif belum tersedia.'):(language==='en'?'The hotel has changed. Check the route in Google Maps; transport options, duration and fare need to be checked again.':'Hotel telah berubah. Periksa rute di Google Maps; pilihan transportasi, durasi, dan tarif perlu diperiksa kembali.')};

const merged=reconcileHotelTransfers(trip,[...existing,...additions],plan.context.language,plan.context.hotelStay?.day).map(item=>{
 // A retained hotel time is not evidence that its arrival transfer has finished.
 // Leave check-in unscheduled instead of inventing a journey duration.
 if(item.category!=='Penginapan'||aiProtected(item)||!existing.includes(item)||!item.time)return item;
 const collision=additions.some(a=>a.category==='Transportasi'&&a.day===item.day&&a.time===item.time);
 return collision?{...item,time:'',note:item.note+(plan.context.language==='en'?' Check-in time is unconfirmed; check in after the arrival transfer.':' Jam check-in belum ditentukan; check-in setelah transfer tiba.')}:item;
});

